# Code generated by Claude
"""
Headless test of the placeholder pedestal lift actuator (src/pedestal.py, robot_specs.PEDESTAL_SPECS).

    source .venv/bin/activate
    python experiments/pedestal_lift_test.py

No viewer, no rendering; one MuJoCo model at a time. Mirrors combined_controller.py: spawn,
1.0 s warm-up with every non-base actuator held, capture the drooped arm pose, 0.4 s re-settle,
then base stationary (velocity drive at zero) while the pedestal command is stepped.

Reports
  * the load the lift carries (body masses above each stage) and the actuator force that holds it
  * base settle z with the actuator on, against the same model without it
  * for each setpoint (fully raised, mid, fully lowered, raised again): time to get within 2 mm
    of the command, then 3 s of hold with the height error in mm
      stage error    MiddleBottom - command
      coupling       TopMiddle - MiddleBottom (should be 0)
      top-of-pedestal height error: the robot body's height above the pedestal base compared with
      its height at the same command from kinematics alone (the stages stack: the top moves 2x)
  * shoulder height above the floor at each setpoint, and whether the workbench top is within the
    arm's reach at fully lowered (straight-arm reach from the shoulder, geometric)
"""

import sys
from pathlib import Path

import mujoco
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src import robot_specs  # noqa: E402
from src.controller import RobotController  # noqa: E402
from src.arm_actuators import add_arm_actuators  # noqa: E402
from src.pedestal import add_pedestal_lift, pedestal_load  # noqa: E402

SCENE = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]
PS = robot_specs.PEDESTAL_SPECS
HOLD_S, MOVE_S, TOL_MM = 3.0, 15.0, 2.0
LOWEST = PS["lowest_command"]                      # "fully lowered" = the reachable limit
SETPOINTS = [("fully raised", 0.0), ("mid", LOWEST / 2), ("fully lowered", LOWEST), ("fully raised again", 0.0)]


def load(with_lift):
    spec = mujoco.MjSpec.from_file(str(SCENE))
    add_arm_actuators(spec)                        # always on, as in RobotSimulator
    if with_lift:
        add_pedestal_lift(spec, PS)
    m = spec.compile()
    m.opt.timestep = robot_specs.SIMULATION_TIMESTEP
    return m


class Sim:
    """Controller-like loop: warm-up, hold arm pose, base stationary."""

    def __init__(self, model):
        self.m, self.d = model, mujoco.MjData(model)
        self.ctrl = RobotController(model)
        wheels = {mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, n) for n in ("left_motor", "right_motor")}
        self.unclaimed = [a for a in range(model.nu) if a not in wheels]
        self.base_dof = model.jnt_dofadr[[j for j in range(model.njnt) if model.jnt_type[j] == 0][0]]
        self.ped = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, PS["actuator_name"])
        self.hold = np.zeros(model.nu)
        self.d.qpos[0:3] = SPAWN
        mujoco.mj_forward(model, self.d)

    def _apply_hold(self):
        pd = self.ctrl.step(self.hold, {"joint_angles": self.d.qpos, "joint_velocities": self.d.qvel})
        self.d.ctrl[:] = 0.0
        self.d.ctrl[self.unclaimed] = pd[self.unclaimed]

    def settle(self):
        """The controller's start-up; returns (z after warm-up, z after re-settle)."""
        m, d = self.m, self.d
        for _ in range(int(round(1.0 * robot_specs.PHYSICS_HZ))):
            self._apply_hold()
            mujoco.mj_step(m, d)
        z1 = float(d.qpos[2])
        for a in self.unclaimed:                                   # capture the drooped pose
            self.hold[a] = d.qpos[m.jnt_qposadr[m.actuator_trnid[a, 0]]]
            d.qvel[m.jnt_dofadr[m.actuator_trnid[a, 0]]] = 0.0
        if self.ped >= 0:
            self.hold[self.ped] = PS["target_height"]
        mujoco.mj_forward(m, d)
        for _ in range(int(round(0.4 * robot_specs.PHYSICS_HZ))):
            self._apply_hold()
            mujoco.mj_step(m, d)
        return z1, float(d.qpos[2])

    def step(self):
        d = self.d
        self._apply_hold()
        d.qvel[self.base_dof + 0:self.base_dof + 2] = 0.0           # base stationary
        d.qvel[self.base_dof + 3:self.base_dof + 6] = 0.0
        mujoco.mj_step(self.m, d)


def main():
    # ---------------------------------------------------------------- baseline (no lift actuator)
    base = Sim(load(False))
    z1_off, z2_off = base.settle()
    pj = {n: base.m.joint(n) for n in PS["joints"]}
    q_sag = {n: float(base.d.qpos[pj[n].qposadr[0]]) * 1000 for n in PS["joints"]}
    print(f"WITHOUT the lift actuator ({base.m.nu} actuators): base z after warm-up {z1_off:.4f} m, after re-settle "
          f"{z2_off:.4f} m; pedestal stages sag to MiddleBottom {q_sag['MiddleBottom']:.1f} mm, "
          f"TopMiddle {q_sag['TopMiddle']:.1f} mm (command 0)")
    del base

    # ---------------------------------------------------------------- with the lift
    m = load(True)
    sim = Sim(m)
    d = sim.d
    print(f"\nWITH the lift actuator ({m.nu} actuators; '{PS['actuator_name']}' = actuator {sim.ped}, "
          f"ctrlrange {m.actuator_ctrlrange[sim.ped]} m, forcerange {m.actuator_forcerange[sim.ped]} N, "
          f"kp {PS['kp']:.3g} N/m, {m.neq} equality constraints)")
    load_ = pedestal_load(m, PS)
    print(f"Load: {load_['mass_above_lower_kg']:.2f} kg above MiddleBottom + {load_['mass_above_upper_kg']:.2f} kg above "
          f"TopMiddle; stages coupled -> the one actuator holds {load_['hold_force_n']:.0f} N "
          f"(static sag at kp {PS['kp']:.3g}: {load_['static_sag_mm']:.2f} mm; forcerange = "
          f"{PS['force_limit'] / load_['hold_force_n']:.1f}x the hold force)")
    z1, z2 = sim.settle()
    print(f"Base settle z: {z1:.4f} m after the 1.0 s warm-up, {z2:.4f} m after the 0.4 s re-settle "
          f"(without the actuator: {z1_off:.4f} / {z2_off:.4f} m)")

    lo_id, up_id = (m.joint(n) for n in PS["joints"])
    q_lo = lambda: float(d.qpos[lo_id.qposadr[0]])
    q_up = lambda: float(d.qpos[up_id.qposadr[0]])
    link0 = m.body("openarm_body_link0").id
    bottom = m.body("pedestal_Bottom").id

    def top_height():
        """Robot body height above the pedestal base, in the pedestal base's frame (tilt-proof)."""
        R = d.xmat[bottom].reshape(3, 3)
        return float((R.T @ (d.xpos[link0] - d.xpos[bottom]))[2])

    # reference: the same height from kinematics with both stages at 0
    d2 = mujoco.MjData(m)
    d2.qpos[:] = d.qpos
    d2.qpos[lo_id.qposadr[0]] = d2.qpos[up_id.qposadr[0]] = 0.0
    mujoco.mj_kinematics(m, d2)
    ref_h = float((d2.xmat[bottom].reshape(3, 3).T @ (d2.xpos[link0] - d2.xpos[bottom]))[2])

    g_torso, g_bottom = m.geom("openarm_body_link0_collision").id, m.geom("pedestal_Bottom_geom").id

    def torso_contact_n():
        """Normal force (N) between the torso collision mesh and pedestal_Bottom."""
        f, total = np.zeros(6), 0.0
        for i in range(d.ncon):
            c = d.contact[i]
            if {c.geom1, c.geom2} == {g_torso, g_bottom}:
                mujoco.mj_contactForce(m, d, i, f)
                total += abs(f[0])
        return total

    shoulder = {s: m.joint(f"openarm_{s}_joint1").id for s in ("left", "right")}
    bench_top = float(d.geom_xpos[m.geom("bench_top").id][2] + m.geom_size[m.geom("bench_top").id][2])
    tcp = m.body("openarm_left_hand_tcp").id
    d3 = mujoco.MjData(m)                                  # straight-arm reach from the shoulder
    d3.qpos[:] = d.qpos
    for a in range(1, 8):
        d3.qpos[m.jnt_qposadr[m.joint(f"openarm_left_joint{a}").id]] = 0.0
    mujoco.mj_kinematics(m, d3)
    reach = float(np.linalg.norm(d3.xpos[tcp] - d3.xanchor[shoulder["left"]]))

    print(f"\n{'setpoint':20s} {'reached':>9s} | {'stage err':>16s} {'coupling':>14s} {'top-height err':>16s} | "
          f"{'actuator force':>14s} | {'shoulder z':>10s} {'bench top':>9s}")
    rows, touches = [], []
    for name, target in SETPOINTS:
        sim.hold[sim.ped] = target
        t_reach = None
        for k in range(int(round(MOVE_S * robot_specs.PHYSICS_HZ))):
            sim.step()
            if abs(q_lo() - target) * 1000 < TOL_MM and t_reach is None:
                t_reach = k / robot_specs.PHYSICS_HZ
        stage, coup, topz, force, touch = [], [], [], [], []
        for _ in range(int(round(HOLD_S * robot_specs.PHYSICS_HZ))):
            sim.step()
            stage.append(1000 * (q_lo() - target))
            coup.append(1000 * (q_up() - q_lo()))
            topz.append(1000 * (top_height() - (ref_h + 2 * target)))
            force.append(float(d.actuator_force[sim.ped]))
            touch.append(torso_contact_n())
        sh = float(d.xanchor[shoulder["left"]][2])
        sh_r = float(d.xanchor[shoulder["right"]][2])
        rows.append((name, target, t_reach, np.array(stage), np.array(coup), np.array(topz), np.array(force), sh, sh_r))
        touches.append(max(touch))
        f = lambda a: f"{a[-1]:+6.2f} (max {np.abs(a).max():.2f})"
        print(f"{name:20s} {('%.1f s' % t_reach) if t_reach is not None else 'NOT in 15s':>9s} | "
              f"{f(rows[-1][3]):>16s} {f(rows[-1][4]):>14s} {f(rows[-1][5]):>16s} | "
              f"{force[-1]:11.0f} N | {sh:8.3f} m {bench_top:7.3f} m")
    print("(errors in mm, at the end of the 3 s hold; max |error| over the hold in brackets)")
    print("Torso / pedestal_Bottom contact force, max over each hold: "
          + ", ".join(f"{r[0]} {t:.0f} N" for r, t in zip(rows, touches)))

    print(f"\nShoulder height above the floor (floor at z = 0; left / right arm joint 1; base z {d.qpos[2]:.3f} m):")
    for name, target, _, _, _, _, _, sh, sh_r in rows:
        print(f"  {name:20s} command {target * 1000:+6.1f} mm per stage -> shoulder {sh:.3f} / {sh_r:.3f} m "
              f"(top of pedestal moves {2000 * target:+.0f} mm)")
    low = next(r for r in rows if r[0] == "fully lowered")
    dz = low[7] - bench_top
    print(f"\nWorkbench: top surface z = {bench_top:.3f} m (bench_top box centre z + half height).")
    print(f"Arm reach from the shoulder, arm straight (hand tcp): {reach:.3f} m.")
    for name, target, _, _, _, _, _, sh, _ in rows[:3]:
        dzv = sh - bench_top
        inreach = abs(dzv) <= reach
        print(f"  {name:14s} shoulder {sh:.3f} m is {abs(dzv) * 1000:.0f} mm {'above' if dzv >= 0 else 'below'} the bench top -> "
              + (f"within reach (hand can touch the bench top out to {np.sqrt(reach**2 - dzv**2):.2f} m horizontally from the shoulder)"
                 if inreach else f"NOT within reach (needs {abs(dzv) * 1000:.0f} mm, reach is {reach * 1000:.0f} mm)"))
    print(f"-> at fully lowered the bench top is {'WITHIN' if abs(dz) <= reach else 'OUT OF'} the arm's reach "
          f"(vertically; the robot has to be driven up to the bench: it is at y = {SPAWN[1]} m, the bench spans y = +-0.8 m).")


if __name__ == "__main__":
    main()
